"""OAM spectrum by root-of-unity testing for the smallest knots."""
from __future__ import annotations
import cmath, math
from typing import Callable, List

def alex_trefoil(z: complex) -> complex:
    return z**2 - z + 1

def alex_cinquefoil(z: complex) -> complex:
    return z**4 - z**3 + z**2 - z + 1

def alex_unknot(z: complex) -> complex:
    return 1.0 + 0j

def oam_spectrum(delta: Callable[[complex], complex], N: int, tol: float = 1e-9) -> List[int]:
    return [l for l in range(N) if abs(delta(cmath.exp(2j*math.pi*l/N))) < tol]

if __name__ == "__main__":
    print("trefoil  (N=6):", oam_spectrum(alex_trefoil, 6))     # [1, 5]
    print("cinquefoil(N=10):", oam_spectrum(alex_cinquefoil, 10)) # [1, 3, 7, 9]
    print("unknot   (N=6):", oam_spectrum(alex_unknot, 6))       # []

"""Structural invariants: reciprocity, normalization, and knot determinants."""
from __future__ import annotations
from typing import Callable

def alex_trefoil(z: complex) -> complex:    return z**2 - z + 1
def alex_figure8(z: complex) -> complex:    return z**2 - 3*z + 1
def alex_cinquefoil(z: complex) -> complex: return z**4 - z**3 + z**2 - z + 1

def determinant(d: Callable[[complex], complex]) -> int:
    return round(abs(d(-1+0j)))

def reciprocity_residual(d: Callable[[complex], complex], deg: int, z: complex) -> float:
    return abs(z**deg * d(1/z) - d(z))

if __name__ == "__main__":
    for name, d, deg in [("trefoil", alex_trefoil, 2),
                          ("figure8", alex_figure8, 2),
                          ("cinquefoil", alex_cinquefoil, 4)]:
        print(f"{name:11s} Delta(1)={round(d(1+0j).real):+d}  det={determinant(d)}"
              f"  recip_res={reciprocity_residual(d, deg, 1.3+0.7j):.1e}")

