function OAM_SPECTRUM(Delta, N, tol):
    spectrum <- empty list
    for l in 0 .. N-1:
        z <- exp(2*pi*i*l/N)
        if |Delta(z)| < tol:
            append l to spectrum
    return spectrum

function ALL_ROOTS_ON_CIRCLE(Delta, tol):
    roots <- roots_of(Delta)
    for z in roots:
        if | |z| - 1 | >= tol:
            return False        // an off-circle root
    return True

