from __future__ import annotations
import cmath
from typing import Tuple

def quadratic_roots(a: float, b: float, c: float) -> Tuple[complex, complex]:
    """Complex-safe roots of a*t^2 + b*t + c."""
    disc: complex = cmath.sqrt(b * b - 4 * a * c)
    return ((-b + disc) / (2 * a), (-b - disc) / (2 * a))

def all_roots_on_unit_circle(roots: Tuple[complex, ...],
                             tol: float = 1e-9) -> bool:
    """True iff every root has modulus 1 (necessary for root-of-unity OAM)."""
    return all(abs(abs(z) - 1.0) < tol for z in roots)

